import sys

def construct_string(a_00, a_01, a_10, a_11):
    # Check if the given counts can form a valid string
    if a_00 + a_01 != a_00 + a_10 or a_01 + a_11 != a_10 + a_11:
        return "Impossible"

    # Construct the string
    result = []
    for _ in range(a_00):
        result.append("00")
    for _ in range(a_01):
        result.append("01")
    for _ in range(a_10):
        result.append("10")
    for _ in range(a_11):
        result.append("11")

    # Check if the constructed string meets the conditions
    count_00 = 0
    count_01 = 0
    count_10 = 0
    count_11 = 0

    for i in range(len(result) - 1):
        if result[i] == "0" and result[i+1] == "0":
            count_00 += 1
        elif result[i] == "0" and result[i+1] == "1":
            count_01 += 1
        elif result[i] == "1" and result[i+1] == "0":
            count_10 += 1
        elif result[i] == "1" and result[i+1] == "1":
            count_11 += 1

    if count_00 == a_00 and count_01 == a_01 and count_10 == a_10 and count_11 == a_11:
        return "".join(result)
    else:
        return "Impossible"

# Read input
input_line = sys.stdin.read().strip()
a_00, a_01, a_10, a_11 = map(int, input_line.split())

# Output the result
print(construct_string(a_00, a_01, a_10, a_11))
